      writeValue(buffer, value.index);
    }    else if (value is NativeListenMode) {
      buffer.putUint8(131);
      writeValue(buffer, value.index);
    }    else if (value is NativeListenState) {
      buffer.putUint8(132);
      writeValue(buffer, value.index);
    }    else if (value is NativeDistanceMethod) {
      buffer.putUint8(133);
      writeValue(buffer, value.index);
    }    else if (value is NativeBox) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is NativeCandidate) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is NativeCameraBatch) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is NativeCameraCapabilities) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is NativeTile) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is NativeStill) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    }    else if (value is NativeScoredLabel) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    }    else if (value is NativeSoundEvent) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    }    else if (value is NativeListenStatus) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    }    else if (value is NativeDistanceCapability) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    }    else if (value is NativeDistance) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : NativeSignalKind.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : NativeThermalLevel.values[value];
      case 131:
        final value = readValue(buffer) as int?;
        return value == null ? null : NativeListenMode.values[value];
      case 132:
        final value = readValue(buffer) as int?;
        return value == null ? null : NativeListenState.values[value];
      case 133:
        final value = readValue(buffer) as int?;
        return value == null ? null : NativeDistanceMethod.values[value];
      case 134:
        return NativeBox.decode(readValue(buffer)!);
      case 135:
        return NativeCandidate.decode(readValue(buffer)!);
      case 136:
        return NativeCameraBatch.decode(readValue(buffer)!);
      case 137:
        return NativeCameraCapabilities.decode(readValue(buffer)!);
      case 138:
        return NativeTile.decode(readValue(buffer)!);
      case 139:
        return NativeStill.decode(readValue(buffer)!);
      case 140:
        return NativeScoredLabel.decode(readValue(buffer)!);
      case 141:
        return NativeSoundEvent.decode(readValue(buffer)!);
      case 142:
        return NativeListenStatus.decode(readValue(buffer)!);
      case 143:
        return NativeDistanceCapability.decode(readValue(buffer)!);
      case 144:
        return NativeDistance.decode(readValue(buffer)!);
      default:
